// throwaway oracle: confirm the string->bytes encoding used by pbkdf2.PBKDF2
const { execFileSync } = require('child_process');
const c = require('crypto');

const cases = [
  ['pässwörd¥', 'sält☃'],
  ['日本語', 'ünïcödé'],
  ['😀', '🎉x'],
  ['a'.repeat(63), 's'],
  ['a'.repeat(64), 's'],
  ['a'.repeat(65), 's'],
  ['é', 'ñ'],
  ['👍🏽', '👨‍👩‍👧'],
  ['', ''],
  ['ÿ', ''],
  ['é', 'à́'],
  ['�inner', 'x'],
];

for (const [p, s] of cases) {
  let out;
  try {
    out = execFileSync('/workspace/dataset/test6_executable', ['--a', p, '--b', s, '--c', p, '--d', s], { encoding: 'utf8' }).split('\n')[0];
  } catch (e) {
    out = 'ERR rc=' + e.status + ' ' + String(e.stderr).trim();
  }
  const utf8 = c.pbkdf2Sync(Buffer.from(p, 'utf8'), Buffer.from(s, 'utf8'), 1000, 16, 'sha1').toString('hex');
  let lat1 = 'n/a';
  try { lat1 = c.pbkdf2Sync(Buffer.from(p, 'latin1'), Buffer.from(s, 'latin1'), 1000, 16, 'sha1').toString('hex'); } catch (e) {}
  console.log(JSON.stringify(p).padEnd(30), 'exe=' + out, '| utf8=' + (out === utf8), '| latin1=' + (out === lat1));
}

