// Independent differential harness (lead's own check, not the workflow's).
// Compares `node /output/test6.mjs` against /workspace/dataset/test6_executable
// on stdout / exit code / stderr, using explicit argv arrays (no shell quoting).
const { execFileSync, spawnSync } = require('child_process');

const EXE = '/workspace/dataset/test6_executable';
const ENTRY = '/output/test6.mjs';

let seed = 0x2f6e2b1;
function rnd() { // xorshift32, deterministic
  seed ^= seed << 13; seed >>>= 0;
  seed ^= seed >>> 17;
  seed ^= seed << 5; seed >>>= 0;
  return seed / 0x100000000;
}
const ri = (n) => Math.floor(rnd() * n);
const pick = (a) => a[ri(a.length)];

const ASCII = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~ ";
const EXOTIC = ['ä', 'ö', '¥', '€', '☃', '日', '本', '語', '😀', '🎉', '👍🏽', 'é', 'ÿ', 'Ω', 'ж', 'م', 'ٱ', '́', '‍', '\t', '\n', '\r', 'ᚠ', '𝔘', '😀'];

function genStr(kind) {
  switch (kind) {
    case 'empty': return '';
    case 'ascii': { const n = ri(40); let s = ''; for (let i = 0; i < n; i++) s += pick(ASCII.split('')); return s; }
    case 'boundary': { const n = pick([1, 31, 32, 55, 56, 57, 63, 64, 65, 119, 120, 127, 128, 129]); return 'a'.repeat(n); }
    case 'mixed': { const n = ri(20); let s = ''; for (let i = 0; i < n; i++) s += rnd() < 0.4 ? pick(EXOTIC) : pick(ASCII.split('')); return s; }
    case 'exotic': { const n = 1 + ri(10); let s = ''; for (let i = 0; i < n; i++) s += pick(EXOTIC); return s; }
    case 'bcrypt': { const b64 = './ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'.split(''); let s = '$2b$12$'; for (let i = 0; i < 22; i++) s += pick(b64); return s; }
    case 'long': { const n = pick([500, 1000, 4096]); let s = ''; for (let i = 0; i < n; i++) s += pick(ASCII.split('')); return s; }
    case 'utf8len64': { // land exactly on the HMAC key threshold with multibyte chars
      const target = pick([62, 63, 64, 65, 66]);
      let s = '', len = 0;
      while (len + 2 <= target) { s += 'ä'; len += 2; }
      while (len < target) { s += 'a'; len += 1; }
      return s;
    }
    default: return 'x';
  }
}

const KINDS = ['empty', 'ascii', 'boundary', 'mixed', 'exotic', 'bcrypt', 'long', 'utf8len64'];

function runBoth(argv) {
  const a = spawnSync(EXE, argv, { encoding: 'buffer', maxBuffer: 1 << 26 });
  const b = spawnSync(process.execPath, [ENTRY, ...argv], { encoding: 'buffer', maxBuffer: 1 << 26 });
  return {
    py: { out: a.stdout.toString('binary'), err: a.stderr.toString('utf8'), rc: a.status },
    js: { out: b.stdout.toString('binary'), err: b.stderr.toString('utf8'), rc: b.status },
  };
}

const PROG_PY = 'test6_executable', PROG_JS = 'test6.mjs';
const normErr = (s, prog) => s.split(prog).join('<PROG>');

let n = 0, badOut = 0, badRc = 0, badErr = 0;
const fails = [];
function check(argv, label) {
  n++;
  const { py, js } = runBoth(argv);
  const outSame = py.out === js.out;
  const rcSame = py.rc === js.rc;
  const errSame = normErr(py.err, PROG_PY) === normErr(js.err, PROG_JS);
  if (!outSame) badOut++;
  if (!rcSame) badRc++;
  if (!errSame) badErr++;
  if (!outSame || !rcSame || !errSame) {
    if (fails.length < 25) fails.push({ label, argv, py, js, outSame, rcSame, errSame });
  }
}

// --- 1. the four documented sample cases -------------------------------------
const SAMPLES = [
  [['--a', 'bhCqzZV^', '--b', '$2b$12$f521Zvhc8Ddk7KB0UzFbyR', '--c', 'wTBxJJ5t', '--d', 'salt_687014'],
    'd713858b808c2134d5ecf896885be611\n9c2031b3ea081155685f2fed421f1862\n'],
  [['--a', '+")$o,oI', '--b', '$2b$12$t3cCqw30fC3hXZpnZVLSw3', '--c', 'v;rAAh+S', '--d', '$2b$12$9WYA6dr3PiS3ipjTu1pW1R'],
    'd15d599af7a913a1533c6a1c77af1278\n5c7a8fc49691faaa2ca4a61be9ae02b5\n'],
  [['--a', '5bHAF_iS', '--b', 'qYgUadyC', '--c', 'jRvWu~j)', '--d', '$2b$12$dgvnmASJU7UIqQstpgdzKJ'],
    'cad8ca47004670ea14e598fb7512cd82\nf82f31ccbd99ed5e572b303b046abd56\n'],
  [['--a', 'Sd9nL1ko', '--b', '626RaGQ9KixMXOoT', '--c', ')uQ*27DZ', '--d', '$2b$12$aTnnrWTZYeKgZ3IlxumDhq'],
    '6d14c175cb02ca2add8e60ea373a34d9\n60b4a756246b08109ea81f67c9b811fe\n'],
];
let sampleFail = 0;
for (const [argv, expected] of SAMPLES) {
  const got = spawnSync(process.execPath, [ENTRY, ...argv], { encoding: 'utf8' }).stdout;
  if (got !== expected) { sampleFail++; console.log('SAMPLE MISMATCH', JSON.stringify(argv), 'got', JSON.stringify(got), 'want', JSON.stringify(expected)); }
  check(argv, 'sample');
}

// --- 2. RFC-6070-ish structural cases + CLI shapes ---------------------------
const CLI_SHAPES = [
  [], ['--a', 'x'], ['--a', 'x', '--b', 'y'], ['--a', 'x', '--b', 'y', '--c', 'z'],
  ['--d', 'w', '--c', 'z', '--b', 'y', '--a', 'x'],
  ['--a=x', '--b=y', '--c=z', '--d=w'], ['--a=', '--b=', '--c=', '--d='],
  ['--a', '', '--b', '', '--c', '', '--d', ''],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w', 'extra'],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w', 'e1', 'e2', '--z'],
  ['--z', '1', '--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '1', '--a', '2', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '2', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['-h'], ['--help'], ['--h'], ['--he'], ['--hel'], ['--help', '--a', 'x'],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w', '-h'],
  ['-hx', '--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['-x', '--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['-a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--A', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--ab', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-5', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-5.5', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-.5', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-1e3', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a=-x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '- x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-x y', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '-', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--b', 'y', '--c', 'z', '--d', 'w', '--a'],
  ['--', '--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', 'x', '--', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w', '--'],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w', '--', 'extra'],
  ['--a=k=v', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', 'a\nb', '--b', 'c\td', '--c', 'e\rf', '--d', ' g '],
  ['--zz=1', '--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
];
for (const argv of CLI_SHAPES) check(argv, 'cli');

// --- 3. random value fuzzing -------------------------------------------------
const N = Number(process.argv[2] || 600);
for (let i = 0; i < N; i++) {
  const argv = ['--a', genStr(pick(KINDS)), '--b', genStr(pick(KINDS)), '--c', genStr(pick(KINDS)), '--d', genStr(pick(KINDS))];
  check(argv, 'fuzz');
}

// --- report ------------------------------------------------------------------
console.log('\n===== LEAD DIFFERENTIAL REPORT =====');
console.log('cases run      :', n);
console.log('sample failures:', sampleFail, '/', SAMPLES.length);
console.log('stdout mismatch:', badOut);
console.log('exitcode mismat:', badRc);
console.log('stderr mismatch:', badErr, '(prog name normalized)');
for (const f of fails) {
  console.log('\n--- FAIL [' + f.label + '] argv=' + JSON.stringify(f.argv));
  if (!f.outSame) console.log('  stdout py=' + JSON.stringify(f.py.out) + '\n         js=' + JSON.stringify(f.js.out));
  if (!f.rcSame) console.log('  rc py=' + f.py.rc + ' js=' + f.js.rc);
  if (!f.errSame) console.log('  stderr py=' + JSON.stringify(f.py.err) + '\n         js=' + JSON.stringify(f.js.err));
}
process.exit(badOut || badRc || sampleFail ? 1 : 0);

