/**
 * Byte-level helpers shared by the hash, MAC and KDF layers.
 *
 * The reference implementation (CPython's `pbkdf2` package) encodes the
 * passphrase and the salt with `str.encode('utf-8')` before feeding them to
 * HMAC, so the port has to reproduce UTF-8 exactly -- including combining
 * surrogate pairs into a single four-byte sequence, and applying no Unicode
 * normalization whatsoever.
 */

/**
 * Encode a JavaScript string to UTF-8 bytes.
 *
 * Iterating with `for...of` walks code points rather than UTF-16 code units,
 * so a surrogate pair such as U+1F600 yields one four-byte sequence
 * (f0 9f 98 80) instead of the six-byte CESU-8 form.
 *
 * @param {string} str
 * @returns {Uint8Array}
 */
export function utf8Encode(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Uint8Array.from(out);
}

/**
 * Coerce a string or byte sequence to a `Uint8Array` of UTF-8 bytes.
 *
 * @param {string|Uint8Array|number[]} value
 * @returns {Uint8Array}
 */
export function toBytes(value) {
  if (typeof value === 'string') return utf8Encode(value);
  if (value instanceof Uint8Array) return value;
  if (Array.isArray(value)) return Uint8Array.from(value);
  throw new TypeError('expected a string or a byte sequence');
}

const HEX = '0123456789abcdef';

/**
 * Render bytes as lowercase hex, matching Python's `bytes.hex()`.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function toHex(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    out += HEX[bytes[i] >> 4] + HEX[bytes[i] & 0x0f];
  }
  return out;
}

/**
 * Concatenate byte arrays into a single buffer.
 *
 * @param {Uint8Array[]} chunks
 * @returns {Uint8Array}
 */
export function concatBytes(chunks) {
  let total = 0;
  for (const chunk of chunks) total += chunk.length;
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

/**
 * XOR `src` into `dst` in place. Both buffers must be the same length.
 *
 * @param {Uint8Array} dst
 * @param {Uint8Array} src
 * @returns {Uint8Array} dst
 */
export function xorInto(dst, src) {
  for (let i = 0; i < dst.length; i++) dst[i] ^= src[i];
  return dst;
}

