/**
 * SHA-1 (FIPS 180-4) implemented from scratch in pure JavaScript.
 *
 * The object exposes a hashlib-shaped interface -- `update()`, `digest()`,
 * `hexdigest()`, `copy()` plus `digest_size` / `block_size` -- so it can be
 * plugged into the HMAC and PBKDF2 layers the same way `hashlib.sha1` is
 * plugged into the Python original.
 */

import { toBytes, toHex } from '../util/bytes.mjs';

export const digest_size = 20;
export const block_size = 64;

/** Round constants for the four 20-round groups. */
const K0 = 0x5a827999;
const K1 = 0x6ed9eba1;
const K2 = 0x8f1bbcdc;
const K3 = 0xca62c1d6;

/**
 * Compress one 64-byte block into the five-word state.
 *
 * Every arithmetic result is folded back into 32 bits with `>>> 0`. The
 * intermediate sums stay well below 2^53, so the additions are exact before
 * the fold.
 *
 * @param {Uint32Array} h five-word state, updated in place
 * @param {Uint8Array} block
 * @param {number} off offset of the block inside `block`
 * @param {Int32Array} w scratch message schedule (80 words)
 */
function compress(h, block, off, w) {
  for (let i = 0; i < 16; i++) {
    const j = off + i * 4;
    w[i] = (block[j] << 24) | (block[j + 1] << 16) | (block[j + 2] << 8) | block[j + 3];
  }
  for (let i = 16; i < 80; i++) {
    const x = w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16];
    w[i] = (x << 1) | (x >>> 31);
  }

  let a = h[0];
  let b = h[1];
  let c = h[2];
  let d = h[3];
  let e = h[4];

  for (let i = 0; i < 80; i++) {
    let f;
    let k;
    if (i < 20) {
      f = (b & c) | (~b & d);
      k = K0;
    } else if (i < 40) {
