/**
 * HMAC (RFC 2104) over any digest module exposing the hashlib-shaped
 * interface from `../hash/sha1.mjs`.
 *
 * Mirrors Python's `hmac.HMAC`: the inner and outer hash states are primed
 * with the keyed pads at construction time, `copy()` snapshots the primed
 * state, and `digest()` leaves the object reusable.
 */

import { sha1Module } from '../hash/sha1.mjs';
import { toBytes, toHex } from '../util/bytes.mjs';

const IPAD_BYTE = 0x36;
const OPAD_BYTE = 0x5c;

export class HMAC {
  /**
   * @param {string|Uint8Array|number[]} key
   * @param {string|Uint8Array|number[]|null} [msg] optional initial message
   * @param {object} [digestmod] digest module descriptor (defaults to SHA-1)
   */
  constructor(key, msg = null, digestmod = sha1Module) {
    this.digestmod = digestmod;
    this.block_size = digestmod.block_size;
    this.digest_size = digestmod.digest_size;

    let keyBytes = toBytes(key);
    // RFC 2104: keys longer than the block size are replaced by their digest.
    // A key of exactly the block size is used as-is.
    if (keyBytes.length > this.block_size) keyBytes = digestmod.digest(keyBytes);

    const ipad = new Uint8Array(this.block_size);
    const opad = new Uint8Array(this.block_size);
    ipad.fill(IPAD_BYTE);
    opad.fill(OPAD_BYTE);
    for (let i = 0; i < keyBytes.length; i++) {
      ipad[i] ^= keyBytes[i];
      opad[i] ^= keyBytes[i];
    }

    this._inner = digestmod.create();
    this._outer = digestmod.create();
    this._inner.update(ipad);
    this._outer.update(opad);

    if (msg !== null && msg !== undefined) this.update(msg);
  }

  /**
   * @param {string|Uint8Array|number[]} msg
   * @returns {HMAC} this
   */
  update(msg) {
    this._inner.update(msg);
    return this;
  }

  /**
   * Snapshot the MAC state. Used by PBKDF2 to re-key once and then fork a
   * fresh MAC per iteration instead of re-deriving the pads 1000 times.
   *
   * @returns {HMAC}
   */
  copy() {
    const clone = Object.create(HMAC.prototype);
    clone.digestmod = this.digestmod;
    clone.block_size = this.block_size;
    clone.digest_size = this.digest_size;
    clone._inner = this._inner.copy();
    clone._outer = this._outer.copy();
    return clone;
  }

  /**
   * @returns {Uint8Array} the MAC of everything absorbed so far
   */
  digest() {
    const outer = this._outer.copy();
    outer.update(this._inner.digest());
    return outer.digest();
  }

  /** @returns {string} lowercase hex MAC */
  hexdigest() {
    return toHex(this.digest());
  }
}

/**
 * MAC module descriptor, the analogue of passing the `hmac` module itself as
 * `macmodule` to Python's `PBKDF2`.
 */
export const hmacModule = {
  name: 'hmac',
  /**
   * @param {string|Uint8Array|number[]} key
   * @param {string|Uint8Array|number[]|null} [msg]
   * @param {object} [digestmod]
   * @returns {HMAC}
   */
  new(key, msg = null, digestmod = sha1Module) {
    return new HMAC(key, msg, digestmod);
  },
};

/**
 * One-shot convenience wrapper.
 *
 * @param {string|Uint8Array|number[]} key
 * @param {string|Uint8Array|number[]} msg
 * @param {object} [digestmod]
 * @returns {Uint8Array}
 */
export function hmacDigest(key, msg, digestmod = sha1Module) {
  return new HMAC(key, msg, digestmod).digest();
}

