/**
 * PBKDF2 (RFC 2898 / PKCS #5 v2.0) as a readable byte stream, matching the
 * interface of the `pbkdf2` PyPI package used by the original script:
 *
 *     pbkdf2.PBKDF2(passphrase, salt).read(16)
 *
 * Defaults are the package's own: 1000 iterations of HMAC-SHA1. `read()` keeps
 * the unconsumed tail of the last derived block, so successive reads walk the
 * key stream instead of restarting it.
 */

import { HMAC } from '../hash/hmac.mjs';
import { sha1Module } from '../hash/sha1.mjs';
import { concatBytes, toBytes, toHex, xorInto } from '../util/bytes.mjs';

/** The `pbkdf2` package's default iteration count. */
export const DEFAULT_ITERATIONS = 1000;

export class PBKDF2 {
  /**
   * @param {string|Uint8Array|number[]} passphrase encoded as UTF-8 if a string
   * @param {string|Uint8Array|number[]} salt encoded as UTF-8 if a string
   * @param {number} [iterations]
   * @param {object} [digestmodule] digest module descriptor (defaults to SHA-1)
   */
  constructor(passphrase, salt, iterations = DEFAULT_ITERATIONS, digestmodule = sha1Module) {
    if (!Number.isInteger(iterations) || iterations < 1) {
      throw new RangeError('iterations must be a positive integer');
    }
    this.iterations = iterations;
    this.digestmodule = digestmodule;
    this.closed = false;

    this._passphrase = toBytes(passphrase);
    this._salt = toBytes(salt);
    this._blockNum = 0;
    this._buf = new Uint8Array(0);
    // Key schedule is fixed for the lifetime of the stream, so prime the MAC
    // once and fork copies per iteration.
    this._prf = new HMAC(this._passphrase, null, digestmodule);
  }

  /**
   * Derive the `i`-th block: U1 xor U2 xor ... xor U_c, with
   * U1 = PRF(P, S || INT_BE32(i)) and U_n = PRF(P, U_{n-1}).
   *
   * @param {number} blockNum 1-based block index
   * @returns {Uint8Array} one digest-sized block
   */
  _deriveBlock(blockNum) {
    const counter = Uint8Array.of(
      (blockNum >>> 24) & 0xff,
      (blockNum >>> 16) & 0xff,
      (blockNum >>> 8) & 0xff,
      blockNum & 0xff,
    );

    let u = this._prf.copy().update(this._salt).update(counter).digest();
    const acc = u.slice();
    for (let i = 1; i < this.iterations; i++) {
      u = this._prf.copy().update(u).digest();
      xorInto(acc, u);
    }
    return acc;
  }

  /**
   * Read the next `bytes` bytes of the derived key stream.
   *
   * @param {number} bytes
   * @returns {Uint8Array}
   */
  read(bytes) {
    if (this.closed) throw new Error('file-like object is closed');
    if (!Number.isInteger(bytes) || bytes < 0) {
      throw new RangeError('bytes must be a non-negative integer');
    }

    const chunks = [this._buf];
    let size = this._buf.length;
    while (size < bytes) {
      this._blockNum += 1;
      const block = this._deriveBlock(this._blockNum);
      chunks.push(block);
      size += block.length;
    }

    const buf = concatBytes(chunks);
    this._buf = buf.slice(bytes);
    return buf.slice(0, bytes);
  }

  /**
   * Read `octets` bytes and return them as lowercase hex.
   *
   * @param {number} octets
   * @returns {string}
   */
  hexread(octets) {
    return toHex(this.read(octets));
  }

  /** Release the key material and forbid further reads. */
  close() {
    if (!this.closed) {
      this._passphrase = new Uint8Array(0);
      this._salt = new Uint8Array(0);
      this._buf = new Uint8Array(0);
      this._prf = null;
      this.closed = true;
    }
  }
}

/**
 * One-shot derivation helper.
 *
 * @param {string|Uint8Array|number[]} passphrase
 * @param {string|Uint8Array|number[]} salt
 * @param {number} dkLen desired key length in bytes
 * @param {number} [iterations]
 * @param {object} [digestmodule]
 * @returns {Uint8Array}
 */
export function pbkdf2(passphrase, salt, dkLen, iterations = DEFAULT_ITERATIONS, digestmodule = sha1Module) {
  return new PBKDF2(passphrase, salt, iterations, digestmodule).read(dkLen);
}

/**
 * One-shot derivation returning lowercase hex, the shape the entry point wants.
 *
 * @param {string|Uint8Array|number[]} passphrase
 * @param {string|Uint8Array|number[]} salt
 * @param {number} dkLen desired key length in bytes
