/**
 * A faithful miniature of the slice of CPython's `argparse` that the original
 * script exercises: long options that take exactly one string value, all
 * required, plus the implicit `-h/--help`.
 *
 * The behaviours reproduced here were pinned by black-box probing the
 * reference build, and follow CPython's own two-phase algorithm:
 *
 *   1. classify every token up front (this is where `ambiguous option` fires,
 *      which is why it outranks every other diagnostic);
 *   2. consume left to right, then check required options, then report
 *      leftovers as `unrecognized arguments`.
 *
 * Notable details that fall out of that ordering:
 *   - `--a 1 --a 2` keeps `2` (last wins);
 *   - `-5`, `-5.5`, `-.5`, `-` and `- x` are usable as values, but `-x` and
 *     `-1e3` are not (they classify as unknown options);
 *   - the first `--` is a hard barrier: it never serves as a value, and it
 *     shows up verbatim in `unrecognized arguments`;
 *   - `--help=x` is an error while `-hx` still prints help.
 */

/** Values matching this are treated as negative numbers, not options. */
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** Column budget for the help layout, mirroring argparse's defaults. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

/**
 * Thrown instead of terminating the process directly, so the entry point can
 * set `process.exitCode` and return -- letting Node flush stdout/stderr rather
 * than truncating a piped write.
 */
export class ParserExit extends Error {
  /**
   * @param {number} code process exit status
   */
  constructor(code) {
    super(`parser exit: ${code}`);
    this.name = 'ParserExit';
    this.code = code;
  }
}

/**
 * Python's `os.path.basename(sys.argv[0])`.
 *
 * @param {string} path
 * @returns {string}
 */
export function basename(path) {
  const i = path.lastIndexOf('/');
  return i === -1 ? path : path.slice(i + 1);
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, stdout?: (s: string) => void, stderr?: (s: string) => void}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? 'prog';
    this._stdout = options.stdout ?? ((s) => process.stdout.write(s));
    this._stderr = options.stderr ?? ((s) => process.stderr.write(s));
    this._prefixChars = '-';
    /** @type {object[]} actions in declaration order */
    this._actions = [];
    /** @type {Map<string, object>} option string -> action, in registration order */
    this._optionStringActions = new Map();

    this.add_argument('-h', '--help', { action: 'help', help: 'show this help message and exit' });
  }

  /**
   * Register an option. Accepts the option strings followed by an optional
   * settings object, e.g. `add_argument('--a', { required: true })`.
   *
   * @param {...(string|object)} args
   * @returns {object} the created action
   */
  add_argument(...args) {
    const optionStrings = [];
    let config = {};
    for (const arg of args) {
      if (typeof arg === 'string') optionStrings.push(arg);
      else config = arg;
    }
    if (optionStrings.length === 0) {
      throw new Error('only optional arguments are supported');
    }

    // dest comes from the first long option, dashes stripped.
    const long = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = config.dest ?? long.replace(/^-+/, '').replace(/-/g, '_');
    const isHelp = config.action === 'help';

    const action = {
      optionStrings,
      dest,
      isHelp,
      nargs: isHelp ? 0 : 1,
      required: isHelp ? false : Boolean(config.required),
      help: config.help ?? null,
      metavar: config.metavar ?? dest.toUpperCase(),
      default: config.default ?? null,
    };

    this._actions.push(action);
    for (const optionString of optionStrings) this._optionStringActions.set(optionString, action);
    return action;
  }

  // -- formatting ------------------------------------------------------------

  /**
   * `argument <name>:` prefix used in error messages -- argparse joins every
   * option string of the action with '/'.
   *
   * @param {object} action
   * @returns {string}
   */
  _actionName(action) {
    return action.optionStrings.join('/');
  }

  /**
   * How an action is shown in the help body, e.g. `-h, --help` or `--a A`.
   *
   * @param {object} action
   * @returns {string}
   */
  _formatInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ');
  }

  /**
   * The single-line usage string. With this parser it is 45 characters wide,
   * comfortably inside argparse's default 78-column budget, so no wrapping
   * logic is needed to stay byte-identical.
   *
   * @returns {string}
   */
  format_usage() {
    const parts = this._actions.map((action) => {
      const body = action.nargs === 0
        ? action.optionStrings[0]
        : `${action.optionStrings[0]} ${action.metavar}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${this.prog}${parts.length ? ' ' + parts.join(' ') : ''}\n`;
  }

  /**
   * The full `--help` page.
   *
   * @returns {string}
   */
  format_help() {
    const invocations = this._actions.map((a) => this._formatInvocation(a));
    const actionMaxLength = Math.max(0, ...invocations.map((s) => s.length + INDENT));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    let out = this.format_usage();
    out += '\noptions:\n';
    this._actions.forEach((action, i) => {
      const invocation = invocations[i];
      if (!action.help) {
        out += `${' '.repeat(INDENT)}${invocation}\n`;
        return;
      }
      const left = `${' '.repeat(INDENT)}${invocation}`;
      out += `${left}${' '.repeat(Math.max(1, helpPosition - left.length))}${action.help}\n`;
    });
    return out;
  }

  /** Print the help page to stdout and exit 0. */
  print_help() {
    this._stdout(this.format_help());
    throw new ParserExit(0);
  }

  /**
   * Print usage plus a diagnostic to stderr and exit 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    this._stderr(this.format_usage());
    this._stderr(`${this.prog}: error: ${message}\n`);
    throw new ParserExit(2);
  }

  // -- classification --------------------------------------------------------

  /**
   * Collect every option this token could be an abbreviation of, mirroring
   * argparse's `_get_option_tuples`.
   *
   * @param {string} token
   * @returns {object[]}
   */
  _getOptionTuples(token) {
    const result = [];
    const chars = this._prefixChars;

    if (chars.includes(token[0]) && chars.includes(token[1])) {
      // Long form: `--pre` or `--pre=value`.
      let prefix = token;
      let explicitArg = null;
      let sep = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        prefix = token.slice(0, eq);
        explicitArg = token.slice(eq + 1);
        sep = '=';
      }
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString.startsWith(prefix)) result.push({ action, optionString, explicitArg, sep });
      }
    } else if (chars.includes(token[0])) {
      // Short form: a single-character option may carry its value glued on.
      const optionPrefix = token;
      const shortOptionPrefix = token.slice(0, 2);
      const shortExplicitArg = token.slice(2);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg, sep: null });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg: null, sep: null });
        }
      }
    }
    return result;
  }

  /**
   * Decide whether a token is an option, and which one.
   *
   * @param {string} token
   * @returns {object|null} null means "this is a positional value"
   */
  _parseOptional(token) {
    if (token === '') return null;
    if (!this._prefixChars.includes(token[0])) return null;

    if (this._optionStringActions.has(token)) {
      return { action: this._optionStringActions.get(token), optionString: token, explicitArg: null, sep: null };
    }
    if (token.length === 1) return null;

    const eq = token.indexOf('=');
    if (eq !== -1) {
      const head = token.slice(0, eq);
      if (this._optionStringActions.has(head)) {
        return {
          action: this._optionStringActions.get(head),
          optionString: head,
          explicitArg: token.slice(eq + 1),
          sep: '=',
        };
      }
    }

    const tuples = this._getOptionTuples(token);
    if (tuples.length > 1) {
      const matches = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number, and no option could be one: it's a value.
    if (NEGATIVE_NUMBER_RE.test(token)) return null;
    // Contains a space: it was meant to be a value.
    if (token.includes(' ')) return null;

    // An option we do not know about.
    return { action: null, optionString: token, explicitArg: null, sep: null };
  }

  // -- parsing ---------------------------------------------------------------

  /**
   * @param {string[]} argv tokens after the program name
   * @returns {{namespace: object, extras: string[]}}
   */
  parse_known_args(argv) {
    // Phase 1: classify every token before consuming anything. Once the first
    // bare `--` is seen, nothing after it is an option.
    const classes = new Array(argv.length);
    let afterSeparator = false;
    for (let i = 0; i < argv.length; i++) {
      if (afterSeparator) {
        classes[i] = { kind: 'value' };
      } else if (argv[i] === '--') {
        classes[i] = { kind: 'separator' };
        afterSeparator = true;
      } else {
        const option = this._parseOptional(argv[i]);
        classes[i] = option === null ? { kind: 'value' } : { kind: 'option', ...option };
      }
    }

    // Phase 2: consume left to right.
    const namespace = {};
    for (const action of this._actions) {
      if (!action.isHelp) namespace[action.dest] = action.default;
    }
    const seen = new Set();
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = classes[i];
      if (token.kind !== 'option' || token.action === null) {
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      const action = token.action;
      if (action.nargs === 0) {
        // `--help=x` is rejected; the glued `-hx` form still fires the action.
        if (token.explicitArg !== null && token.sep === '=') {
          this.error(`argument ${this._actionName(action)}: ignored explicit argument '${token.explicitArg}'`);
        }
        seen.add(action);
        if (action.isHelp) this.print_help();
        i += 1;
        continue;
      }

      let value;
      if (token.explicitArg !== null) {
        value = token.explicitArg;
        i += 1;
      } else {
        const next = i + 1 < argv.length ? classes[i + 1] : null;
        if (next === null || next.kind !== 'value') {
          this.error(`argument ${this._actionName(action)}: expected one argument`);
        }
        value = argv[i + 1];
        i += 2;
      }
      namespace[action.dest] = value;
      seen.add(action);
    }

    // Phase 3: required options, in declaration order, before leftovers.
    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => this._actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /**
   * @param {string[]} argv tokens after the program name
   * @returns {object} the populated namespace
   */
  parse_args(argv) {
    const { namespace, extras } = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

