      const shortOptionPrefix = token.slice(0, 2);
      const shortExplicitArg = token.slice(2);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg, sep: null });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg: null, sep: null });
        }
      }
    }
    return result;
  }

  /**
   * Decide whether a token is an option, and which one.
   *
   * @param {string} token
   * @returns {object|null} null means "this is a positional value"
   */
  _parseOptional(token) {
    if (token === '') return null;
    if (!this._prefixChars.includes(token[0])) return null;

    if (this._optionStringActions.has(token)) {
      return { action: this._optionStringActions.get(token), optionString: token, explicitArg: null, sep: null };
    }
    if (token.length === 1) return null;

    const eq = token.indexOf('=');
    if (eq !== -1) {
      const head = token.slice(0, eq);
      if (this._optionStringActions.has(head)) {
        return {
          action: this._optionStringActions.get(head),
          optionString: head,
          explicitArg: token.slice(eq + 1),
          sep: '=',
        };
      }
    }

    const tuples = this._getOptionTuples(token);
    if (tuples.length > 1) {
      const matches = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number, and no option could be one: it's a value.
    if (NEGATIVE_NUMBER_RE.test(token)) return null;
    // Contains a space: it was meant to be a value.
    if (token.includes(' ')) return null;

    // An option we do not know about.
    return { action: null, optionString: token, explicitArg: null, sep: null };
  }

  // -- parsing ---------------------------------------------------------------

  /**
   * @param {string[]} argv tokens after the program name
   * @returns {{namespace: object, extras: string[]}}
   */
  parse_known_args(argv) {
    // Phase 1: classify every token before consuming anything. Once the first
    // bare `--` is seen, nothing after it is an option.
    const classes = new Array(argv.length);
    let afterSeparator = false;
    for (let i = 0; i < argv.length; i++) {
      if (afterSeparator) {
        classes[i] = { kind: 'value' };
      } else if (argv[i] === '--') {
        classes[i] = { kind: 'separator' };
        afterSeparator = true;
      } else {
        const option = this._parseOptional(argv[i]);
        classes[i] = option === null ? { kind: 'value' } : { kind: 'option', ...option };
      }
    }

    // Phase 2: consume left to right.
    const namespace = {};
    for (const action of this._actions) {
      if (!action.isHelp) namespace[action.dest] = action.default;
    }
    const seen = new Set();
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = classes[i];
      if (token.kind !== 'option' || token.action === null) {
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      const action = token.action;
      if (action.nargs === 0) {
        // `--help=x` is rejected; the glued `-hx` form still fires the action.
        if (token.explicitArg !== null && token.sep === '=') {
          this.error(`argument ${this._actionName(action)}: ignored explicit argument '${token.explicitArg}'`);
        }
        seen.add(action);
        if (action.isHelp) this.print_help();
        i += 1;
        continue;
      }

      let value;
      if (token.explicitArg !== null) {
        value = token.explicitArg;
        i += 1;
      } else {
        const next = i + 1 < argv.length ? classes[i + 1] : null;
        if (next === null || next.kind !== 'value') {
          this.error(`argument ${this._actionName(action)}: expected one argument`);
        }
        value = argv[i + 1];
        i += 2;
      }
      namespace[action.dest] = value;
      seen.add(action);
    }

    // Phase 3: required options, in declaration order, before leftovers.
    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => this._actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /**
   * @param {string[]} argv tokens after the program name
   * @returns {object} the populated namespace
   */
  parse_args(argv) {
    const { namespace, extras } = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

