#!/usr/bin/env node
/**
 * Node.js port of /workspace/dataset/test6.py
 *
 *     key1 = pbkdf2.PBKDF2(args.a, args.b).read(16)
 *     print(key1.hex())
 *     key2 = pbkdf2.PBKDF2(args.c, args.d).read(16)
 *     print(key2.hex())
 *
 * The `pbkdf2` package defaults to 1000 iterations of HMAC-SHA1, and encodes
 * the passphrase and salt as UTF-8. Everything is implemented from scratch in
 * the local modules below -- no external packages, no built-in crypto.
 */

import { ArgumentParser, ParserExit, basename } from './lib/cli/argparse.mjs';
import { PBKDF2 } from './lib/kdf/pbkdf2.mjs';
import { toHex } from './lib/util/bytes.mjs';

/**
 * Build the parser declared by the original script.
 *
 * @param {string} prog program name shown in usage and error messages
 * @returns {ArgumentParser}
 */
export function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  parser.add_argument('--a', { required: true }); // passphrase1
  parser.add_argument('--b', { required: true }); // salt1
  parser.add_argument('--c', { required: true }); // passphrase2
  parser.add_argument('--d', { required: true }); // salt2
  return parser;
}

/**
 * @param {string[]} argv tokens after the program name
 * @param {string} prog program name
 * @returns {number} process exit status
 */
export function main(argv, prog) {
  const parser = buildParser(prog);
  let args;
  try {
    args = parser.parse_args(argv);
  } catch (err) {
    if (err instanceof ParserExit) return err.code;
    throw err;
  }

  // First PBKDF2 derivation.
  const key1 = new PBKDF2(args.a, args.b).read(16);
  console.log(toHex(key1));

  // Second PBKDF2 derivation.
  const key2 = new PBKDF2(args.c, args.d).read(16);
  console.log(toHex(key2));

  return 0;
}

process.exitCode = main(process.argv.slice(2), basename(process.argv[1] ?? 'test6.mjs'));

